import { execution } from "@dynatrace-sdk/automation-utils";

async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error("HTTP " + resp.status + " for " + url);
  return await resp.text();
}

export default async function () {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};
  const docsSitemapUrlRaw = String(workflowInput.docsSitemapUrl ?? workflowParams.docsSitemapUrl ?? "").trim();
  const docsSitemapUrl = docsSitemapUrlRaw || "https://docs.dynatrace.com/docs/sitemap.xml";

  const sitemap = await getText(docsSitemapUrl);
  const matches = [...sitemap.matchAll(/oneagent\/sprint-(\d+)/g)].map((m) => Number(m[1]));
  if (!matches.length) throw new Error("No sprint links found in docs sitemap");

  const latestSprint = Math.max(...matches);
  const latestRelease = "1." + latestSprint;
  const sprintUrl = "https://docs.dynatrace.com/docs/whats-new/oneagent/sprint-" + latestSprint;
  const sprintHtml = await getText(sprintUrl);

  const essMatch = sprintHtml.match(/Enterprise Success and Support[\s\S]*?(1\.\d{3})/i);
  if (!essMatch) throw new Error("Could not parse ESS oldest supported version");
  const oldestSupportedEss = essMatch[1];

  return {
    latest_release: latestRelease,
    oldest_supported_ess: oldestSupportedEss,
    fetched_at: new Date().toISOString(),
    source_url: sprintUrl
  };
}

import { execution, result } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

// Set to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).
// Token needs: events.ingest
async function resolveRumTokenVaultId() {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};
  return String(workflowInput.rumTokenVaultId ?? workflowParams.rumTokenVaultId ?? "").trim();
}

async function resolveToken(id) {
  const normalized = (id || '').trim();
  if (!normalized) throw new Error('RUM_TOKEN_VAULT_ID is empty.');
  if (!normalized.startsWith('CREDENTIALS_VAULT-')) {
    throw new Error('RUM_TOKEN_VAULT_ID must be a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).');
  }

  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}. Ensure the entry type is "Token" and the workflow has access.`);
  }
  return credentials.token;
}

export default async function () {
  const rumTokenVaultId = await resolveRumTokenVaultId();
  if (!rumTokenVaultId) {
    throw new Error('Missing required workflow input rumTokenVaultId (Credential Vault ID).');
  }

  const versions = await result('oneagent_collect_release_baseline');
  const apiToken = await resolveToken(rumTokenVaultId);

  const envUrl = (getEnvironmentUrl() || '').trim();
  if (!envUrl) throw new Error('getEnvironmentUrl() returned an empty value.');

  const env = new URL(envUrl);
  env.host = env.host.replace('.apps.', '.');
  env.pathname = '';
  env.search = '';
  env.hash = '';

  const baseUrl = env.toString().replace(/\/$/, '');

  const event = {
    eventType: 'CUSTOM_ANNOTATION',
    title: `OneAgentBaseline|${versions.latest_release}|${versions.oldest_supported_ess}|${versions.fetched_at}`,
    description: `OneAgent release baseline sync from ${versions.source_url}`,
    properties: {
      latest_release: versions.latest_release,
      oldest_supported_ess: versions.oldest_supported_ess,
      fetched_at: versions.fetched_at,
      source_url: versions.source_url
    }
  };

  const resp = await fetch(`${baseUrl}/api/v2/events/ingest`, {
    method: 'POST',
    headers: {
      Authorization: `Api-Token ${apiToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(event)
  });

  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`Events ingest failed: HTTP 401 ${body}. Token authentication failed for vault credential ${rumTokenVaultId}.`);
    }
    throw new Error(`Events ingest failed: HTTP ${resp.status} ${body}`);
  }

  return { stored: true };
}

import { execution } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

let DT_API_TOKEN = "";

// Set to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).
// Token needs: RumJavaScriptTagManagement + events.ingest
// Optional for human-readable tag labels: rumManualInsertionTags.read
async function resolveRumTokenVaultId() {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};
  return String(workflowInput.rumTokenVaultId ?? workflowParams.rumTokenVaultId ?? "").trim();
}

async function loadToken(rumTokenVaultId) {
  if (!rumTokenVaultId) {
    throw new Error("Missing required workflow input rumTokenVaultId (Credential Vault ID).");
  }

  const normalized = (rumTokenVaultId || "").trim();
  if (!normalized) throw new Error("RUM_TOKEN_VAULT_ID is empty.");
  if (!normalized.startsWith("CREDENTIALS_VAULT-")) {
    throw new Error("RUM_TOKEN_VAULT_ID must be a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).");
  }

  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}. Ensure the entry type is \"Token\" and the workflow has access.`);
  }
  DT_API_TOKEN = credentials.token;
}

async function dtGetJson(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`GET ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${rumTokenVaultId}.`);
    }
    throw new Error(`GET ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return await resp.json();
}

async function dtGetText(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`GET ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${rumTokenVaultId}.`);
    }
    throw new Error(`GET ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return (await resp.text()).trim();
}

async function dtTryGetText(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    return "";
  }
  return await resp.text();
}

async function dtPostJson(url, payload) {
  const resp = await fetch(url, {
    method: "POST",
    headers: { Authorization: `Api-Token ${DT_API_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`POST ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${rumTokenVaultId}.`);
    }
    throw new Error(`POST ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return await resp.text();
}

function normalizeVersion(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

function toComparableBigInt(value) {
  const normalized = normalizeVersion(value);
  if (!/^\d+$/.test(normalized)) return null;
  return BigInt(normalized);
}

function pickSupportFloor(configuredVersions) {
  const candidates = [
    normalizeVersion(configuredVersions.latestIESupported),
    normalizeVersion(configuredVersions.latestIE11Supported)
  ].filter((v) => /^\d+$/.test(v));

  if (!candidates.length) return "";
  return candidates.reduce((min, current) => {
    if (BigInt(current) < BigInt(min)) return current;
    return min;
  });
}

function pickEffectiveTarget(configuredVersions, latestVersion) {
  const custom = normalizeVersion(configuredVersions.custom);
  if (/^\d+$/.test(custom) && custom !== "0") {
    return { targetVersion: custom, targetPolicy: "custom" };
  }

  const latestStable = normalizeVersion(configuredVersions.latestStable);
  if (/^\d+$/.test(latestStable)) {
    return { targetVersion: latestStable, targetPolicy: "latest_stable" };
  }

  const previousStable = normalizeVersion(configuredVersions.previousStable);
  if (/^\d+$/.test(previousStable)) {
    return { targetVersion: previousStable, targetPolicy: "previous_stable_fallback" };
  }

  return { targetVersion: normalizeVersion(latestVersion), targetPolicy: "latest_available_fallback" };
}

function computePolicyStatus(currentVersion, targetVersion, supportFloorVersion) {
  const currentBig = toComparableBigInt(currentVersion);
  const targetBig = toComparableBigInt(targetVersion);
  const supportFloorBig = toComparableBigInt(supportFloorVersion);

  if (currentBig === null || targetBig === null) {
    return "unknown";
  }
  if (supportFloorBig !== null && currentBig < supportFloorBig) {
    return "unsupported";
  }
  if (currentBig === targetBig) {
    return "on_target";
  }
  if (currentBig > targetBig) {
    return "above_target";
  }
  return "below_target";
}

function extractHumanReadableVersionLabel(text) {
  const source = String(text || "");
  const patterns = [
    /\b1\.\d+\.\d+\.\d{8}-\d{6}\b/,
    /\b1\.\d+\.\d+\.\d+\.\d{8}-\d{6}\b/,
    /\b1\.\d+\.\d+\.\d{8}\b/
  ];

  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match) {
      return match[0];
    }
  }
  return "";
}

function summarizeTargetLabel(apps) {
  const labels = [...new Set(apps.map((app) => normalizeVersion(app.humanReadableTargetLabel)).filter(Boolean))];
  if (labels.length === 1) return labels[0];
  return "";
}

async function mapConcurrent(items, concurrency, fn) {
  const out = new Array(items.length);
  let idx = 0;
  async function worker() {
    while (true) {
      const current = idx++;
      if (current >= items.length) return;
      out[current] = await fn(items[current], current);
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, Math.max(1, items.length)) }, worker));
  return out;
}

export default async function () {
  await execution();
  const rumTokenVaultId = await resolveRumTokenVaultId();
  await loadToken(rumTokenVaultId);

  const envUrl = (getEnvironmentUrl() || "").trim();
  if (!envUrl) throw new Error("getEnvironmentUrl() returned an empty value.");

  const env = new URL(envUrl);
  env.host = env.host.replace(".apps.", ".");
  env.pathname = "";
  env.search = "";
  env.hash = "";

  const baseUrl = env.toString().replace(/\/$/, "");
  const fetchedAt = new Date().toISOString();

  const manualApps = await dtGetJson(`${baseUrl}/api/v1/rum/manualApps`);
  if (!Array.isArray(manualApps)) throw new Error("Expected /api/v1/rum/manualApps to return an array");

  const latestVersion = normalizeVersion(await dtGetText(`${baseUrl}/api/v1/rum/jsLatestVersion`));
  const configuredVersions = await dtGetJson(`${baseUrl}/api/v1/rum/jsConfiguredVersions`);
  const { targetVersion, targetPolicy } = pickEffectiveTarget(configuredVersions, latestVersion);
  const supportFloorVersion = pickSupportFloor(configuredVersions);
  const oldestSupportedVersion = supportFloorVersion || "N/A";

  if (!latestVersion) throw new Error("Could not resolve latest RUM Classic JS version from /api/v1/rum/jsLatestVersion");
  if (!targetVersion) throw new Error("Could not resolve effective target RUM Classic JS version from configured policy");

  const enriched = await mapConcurrent(manualApps, 5, async (app) => {
    const applicationId = app.applicationId;
    const displayName = app.displayName || applicationId;
    const jsVersion = await dtGetText(`${baseUrl}/api/v1/rum/appRevision/${applicationId}`);
    const javaScriptTag = await dtTryGetText(`${baseUrl}/api/v2/rum/javaScriptTag/${applicationId}`);
    const inlineCode = javaScriptTag ? "" : await dtTryGetText(`${baseUrl}/api/v2/rum/inlineCode/${applicationId}`);
    let humanReadableTargetLabel = extractHumanReadableVersionLabel(javaScriptTag || inlineCode);
    if (!humanReadableTargetLabel) {
      humanReadableTargetLabel = jsVersion;
    }
    return { applicationId, displayName, jsVersion, humanReadableTargetLabel };
  });

  let effectiveTargetLabel = summarizeTargetLabel(enriched);
  if (!effectiveTargetLabel) {
    effectiveTargetLabel = targetVersion;
  }
  const ingestUrl = `${baseUrl}/api/v2/events/ingest`;

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSBaseline|${latestVersion}|${oldestSupportedVersion}|${fetchedAt}`,
    description: "RUM Classic JS baseline sync (latest, oldest supported, and effective target)",
    properties: {
      source: "rum_classic_baseline",
      latest_version: latestVersion,
      oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
      effective_target_version: targetVersion,
      effective_target_policy: targetPolicy,
      effective_target_label: effectiveTargetLabel,
      latest_stable: normalizeVersion(configuredVersions.latestStable),
      previous_stable: normalizeVersion(configuredVersions.previousStable),
      latest_ie_supported: normalizeVersion(configuredVersions.latestIESupported),
      latest_ie11_supported: normalizeVersion(configuredVersions.latestIE11Supported),
      custom_configured_version: normalizeVersion(configuredVersions.custom),
      fetched_at: fetchedAt
    }
  });

  await mapConcurrent(enriched, 5, async (app) => {
    let label = normalizeVersion(app.humanReadableTargetLabel);
    if (!label) label = app.jsVersion;
    await dtPostJson(ingestUrl, {
      eventType: "CUSTOM_ANNOTATION",
      title: `RUMJSVersion|${app.applicationId}|${app.jsVersion}|${fetchedAt}`,
      description: `RUM Classic JS library version for ${app.displayName}`,
      properties: {
        source: "rum_classic_api",
        application_id: app.applicationId,
        application_name: app.displayName,
        js_library_version: app.jsVersion,
        human_readable_target_label: label,
        fetched_at: fetchedAt
      }
    });
  });

  const byVersion = {};
  const policyCounts = {
    on_target: 0,
    below_target: 0,
    unsupported: 0,
    above_target: 0,
    unknown: 0
  };

  for (const app of enriched) {
    byVersion[app.jsVersion] = (byVersion[app.jsVersion] || 0) + 1;
    const status = computePolicyStatus(app.jsVersion, targetVersion, supportFloorVersion);
    policyCounts[status] = (policyCounts[status] || 0) + 1;
  }

  await mapConcurrent(enriched, 5, async (app) => {
    const status = computePolicyStatus(app.jsVersion, targetVersion, supportFloorVersion);
    let label = normalizeVersion(app.humanReadableTargetLabel);
    if (!label) label = app.jsVersion;
    await dtPostJson(ingestUrl, {
      eventType: "CUSTOM_ANNOTATION",
      title: `RUMJSPolicyApp|${app.applicationId}|${status}|${fetchedAt}`,
      description: `RUM Classic JS policy status for ${app.displayName}`,
      properties: {
        source: "rum_classic_policy_app",
        application_id: app.applicationId,
        application_name: app.displayName,
        js_library_version: app.jsVersion,
        human_readable_target_label: label,
        effective_target_version: targetVersion,
        effective_target_policy: targetPolicy,
        effective_target_label: effectiveTargetLabel,
        latest_version: latestVersion,
        oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
        policy_status: status,
        fetched_at: fetchedAt
      }
    });
  });

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSVersionSyncSummary|${enriched.length}|${Object.keys(byVersion).length}|${fetchedAt}`,
    description: "RUM Classic JS version sync summary",
    properties: {
      source: "rum_classic_api",
      app_count: String(enriched.length),
      versions_found: String(Object.keys(byVersion).length),
      fetched_at: fetchedAt
    }
  });

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSPolicySummary|${policyCounts.on_target}|${policyCounts.below_target}|${policyCounts.unsupported}|${fetchedAt}`,
    description: "RUM Classic JS policy status summary",
    properties: {
      source: "rum_classic_policy_summary",
      apps_on_target: String(policyCounts.on_target),
      apps_below_target: String(policyCounts.below_target),
      apps_unsupported: String(policyCounts.unsupported),
      apps_above_target: String(policyCounts.above_target),
      apps_unknown: String(policyCounts.unknown),
      effective_target_version: targetVersion,
      effective_target_policy: targetPolicy,
      effective_target_label: effectiveTargetLabel,
      latest_version: latestVersion,
      oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
      fetched_at: fetchedAt
    }
  });

  return {
    fetched_at: fetchedAt,
    latest_version: latestVersion,
    oldest_supported_version: oldestSupportedVersion,
    effective_target_version: targetVersion,
    effective_target_policy: targetPolicy,
    effective_target_label: effectiveTargetLabel,
    app_count: enriched.length,
    versions_found: Object.keys(byVersion).length,
    policy_status: policyCounts,
    by_version: byVersion
  };
}

import { execution } from "@dynatrace-sdk/automation-utils";

async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error("HTTP " + resp.status + " for " + url);
  return await resp.text();
}

function uniqueBy(items, keyFn) {
  const out = [];
  const seen = new Set();
  for (const item of items) {
    const key = keyFn(item);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function parseSprintEntry(url) {
  const m = url.match(/\/sprint-(\d+)/);
  if (!m) return null;
  const sprint = Number(m[1]);
  return { version: "1." + sprint, sort_a: sprint, sort_b: 0, sort_c: 0, url };
}

function parseOperatorEntry(url) {
  const m = url.match(/dto-fix-(\d+)-(\d+)-(\d+)/);
  if (!m) return null;
  return {
    version: String(Number(m[1])) + "." + String(Number(m[2])) + "." + String(Number(m[3])),
    sort_a: Number(m[1]),
    sort_b: Number(m[2]),
    sort_c: Number(m[3]),
    url
  };
}

function parseEdgeconnectEntry(url) {
  const m = url.match(/edgeconnect-release-notes-(\d+)-(\d+)-(\d+)/);
  if (!m) return null;
  return {
    version: String(Number(m[1])) + "." + String(Number(m[2])) + "." + String(Number(m[3])),
    sort_a: Number(m[1]),
    sort_b: Number(m[2]),
    sort_c: Number(m[3]),
    url
  };
}

function parseEntriesFromSitemap(sitemap, component) {
  const regex = new RegExp("<loc>(https://docs\\.dynatrace\\.com/docs/whats-new/" + component.path + "/[^<]+)</loc>", "g");
  const urls = [...sitemap.matchAll(regex)].map((m) => m[1]);

  const parser = component.mode === "sprint" ? parseSprintEntry
    : component.mode === "operator_semver" ? parseOperatorEntry
    : parseEdgeconnectEntry;

  const entries = uniqueBy(urls.map((u) => parser(u)).filter(Boolean), (e) => e.url);
  entries.sort((a, b) => {
    if (b.sort_a !== a.sort_a) return b.sort_a - a.sort_a;
    if (b.sort_b !== a.sort_b) return b.sort_b - a.sort_b;
    return b.sort_c - a.sort_c;
  });
  return entries;
}

export default async function () {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};

  const docsSitemapUrlRaw = String(workflowInput.docsSitemapUrl ?? workflowParams.docsSitemapUrl ?? "").trim();
  const docsSitemapUrl = docsSitemapUrlRaw || "https://docs.dynatrace.com/docs/sitemap.xml";

  const components = [
    { component: "saas", path: "saas", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/saas" },
    { component: "oneagent", path: "oneagent", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/oneagent" },
    { component: "activegate", path: "activegate", mode: "sprint", index_url: "https://docs.dynatrace.com/docs/whats-new/activegate" },
    { component: "operator", path: "dynatrace-operator", mode: "operator_semver", index_url: "https://docs.dynatrace.com/docs/whats-new/dynatrace-operator" },
    { component: "edgeconnect", path: "edgeconnect", mode: "edgeconnect_semver", index_url: "https://docs.dynatrace.com/docs/whats-new/edgeconnect" }
  ];

  const fetched_at = new Date().toISOString();
  const sitemap = await getText(docsSitemapUrl);
  const release_rows = [];
  const release_catalog = {};

  for (const c of components) {
    const entries = parseEntriesFromSitemap(sitemap, c);
    release_catalog[c.component] = entries.slice(0, 15).map((e) => ({ version: e.version, release_url: e.url }));

    const latest = entries[0];
    const nextPublished = entries[1];

    release_rows.push({
      component: c.component,
      released_version: latest ? latest.version : "",
      release_status: latest ? "current" : "unavailable",
      rollout_start_date: "",
      is_latest: "true",
      is_next_planned: "false",
      release_url: latest ? latest.url : c.index_url,
      index_url: c.index_url,
      fetched_at
    });

    release_rows.push({
      component: c.component,
      released_version: nextPublished ? nextPublished.version : "Not yet published",
      release_status: nextPublished ? "current" : "not_yet_published",
      rollout_start_date: "",
      is_latest: "false",
      is_next_planned: "true",
      release_url: nextPublished ? nextPublished.url : c.index_url,
      index_url: c.index_url,
      fetched_at
    });
  }

  const summary_prompt = release_rows
    .filter((r) => r.is_latest === "true")
    .map((r) => r.component + ": " + (r.released_version || "unavailable") + " " + r.release_url)
    .join("\n");

  const ai_summary_prompt = components.map((c) => {
    const lines = (release_catalog[c.component] || []).slice(0, 5).map((entry) => c.component + "|" + entry.version + "|" + entry.release_url);
    return lines.join("\n");
  }).filter(Boolean).join("\n");

  return {
    fetched_at,
    release_rows,
    release_catalog,
    summary_prompt,
    ai_summary_prompt,
    release_catalog_count: Object.values(release_catalog).reduce((n, rows) => n + rows.length, 0)
  };
}

import { execution } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

async function resolveApiTokenVaultId() {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};
  const value = String(workflowInput.apiTokenVaultId ?? workflowParams.apiTokenVaultId ?? "").trim();
  if (!value) {
    throw new Error("Missing required workflow input apiTokenVaultId (Credential Vault ID).");
  }
  if (!value.startsWith("CREDENTIALS_VAULT-")) {
    throw new Error("apiTokenVaultId must be a Credential Vault ID in format CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx.");
  }
  return value;
}

async function resolveToken(id) {
  const credentials = await credentialVaultClient.getCredentialsDetails({ id });
  if (!credentials || !credentials.token) throw new Error("No token in vault " + id);
  return credentials.token;
}

export default async function () {
  await execution();
  const apiTokenVaultId = await resolveApiTokenVaultId();
  const fetched_at = new Date().toISOString();
  try {
    const apiToken = await resolveToken(apiTokenVaultId);
    const envUrl = String(getEnvironmentUrl() || "").trim();
    if (!envUrl) throw new Error("getEnvironmentUrl() returned an empty value.");

    const env = new URL(envUrl);
    env.host = env.host.replace(".apps.", ".");
    env.pathname = "/api/v1/config/clusterversion";
    env.search = "";
    env.hash = "";

    const resp = await fetch(env.toString(), { headers: { Authorization: "Api-Token " + apiToken } });
    if (!resp.ok) throw new Error("HTTP " + resp.status);
    const body = await resp.json();

    return {
      runtime_rows: [{
        component: "saas",
        observed_version: String(body.version || ""),
        running_count: "1",
        source_type: "cluster_version_api",
        source_status: "current",
        observed_at: fetched_at,
        collection_message: ""
      }]
    };
  } catch (error) {
    return {
      runtime_rows: [{
        component: "saas",
        observed_version: "",
        running_count: "0",
        source_type: "cluster_version_api",
        source_status: "unavailable",
        observed_at: fetched_at,
        collection_message: String(error)
      }]
    };
  }
}

import { result } from "@dynatrace-sdk/automation-utils";

const COMPONENT_MODE = {
  saas: "sprint",
  oneagent: "sprint",
  activegate: "sprint",
  operator: "semver",
  edgeconnect: "semver"
};

function unavailableRow(component, observedAt, message, sourceType = "pending_source_validation") {
  return {
    component,
    observed_version: "",
    running_count: "0",
    source_type: sourceType,
    source_status: "unavailable",
    observed_at: observedAt,
    collection_message: message
  };
}

function parseVersionParts(version, mode) {
  const text = String(version || "").trim();
  if (!text) return null;

  if (mode === "sprint") {
    // Accept both release notation (1.345) and runtime build notation (1.345.20.20260804-171011).
    const m = text.match(/^1\.(\d+)(?:\.|$)/);
    if (!m) return null;
    return [1, Number(m[1]), 0];
  }

  // Accept semver with optional build suffixes by taking the leading three numeric segments.
  const m = text.match(/^(\d+)\.(\d+)\.(\d+)(?:\.|-|$)/);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

function compareVersions(a, b, mode) {
  const pa = parseVersionParts(a, mode);
  const pb = parseVersionParts(b, mode);
  if (!pa && !pb) return 0;
  if (!pa) return -1;
  if (!pb) return 1;
  for (let i = 0; i < 3; i += 1) {
    if (pa[i] !== pb[i]) return pa[i] - pb[i];
  }
  return 0;
}

function normalizeOneAgent(records, observedAt) {
  const out = [];
  const rows = Array.isArray(records) ? records : [];
  for (const r of rows) {
    const version = String(r.installerVersion || r.oneagent_version || "").trim();
    const count = r.hosts ?? r.count ?? 0;
    if (!version) continue;
    out.push({
      component: "oneagent",
      observed_version: version,
      running_count: String(count),
      source_type: "dql_host_installerVersion",
      source_status: "current",
      observed_at: observedAt,
      collection_message: ""
    });
  }
  if (!out.length) {
    out.push(unavailableRow("oneagent", observedAt, "No OneAgent runtime rows returned", "dql_host_installerVersion"));
  }
  return out;
}

function rowsFromTaskPayload(taskResult, component, observedAt) {
  const rows = Array.isArray(taskResult?.runtime_rows) ? taskResult.runtime_rows : [];
  if (rows.length) return rows;
  return [unavailableRow(component, observedAt, "No runtime payload from " + component + " collector")];
}

function normalizeDistributionRows({ component, records, versionField, countField, observedAt, sourceType }) {
  const out = [];
  const rows = Array.isArray(records) ? records : [];
  for (const r of rows) {
    const version = String(r?.[versionField] || "").trim();
    const count = r?.[countField] ?? 0;
    if (!version) continue;
    out.push({
      component,
      observed_version: version,
      running_count: String(count),
      source_type: sourceType,
      source_status: "current",
      observed_at: observedAt,
      collection_message: ""
    });
  }

  if (!out.length) {
    return [unavailableRow(component, observedAt, "No " + component + " runtime rows returned", sourceType)];
  }

  return out;
}

function normalizeOperatorRows(records, observedAt) {
  const rows = Array.isArray(records) ? records : [];
  const clusterCountRaw = rows[0]?.cluster_count ?? 0;
  const clusterCount = Number(clusterCountRaw || 0);

  if (!Number.isFinite(clusterCount) || clusterCount <= 0) {
    return [{
      component: "operator",
      observed_version: "",
      running_count: "0",
      source_type: "dql_kubernetes_cluster_inventory",
      source_status: "not_configured",
      observed_at: observedAt,
      collection_message: "No Kubernetes clusters detected in tenant"
    }];
  }

  return [{
    component: "operator",
    observed_version: "",
    running_count: String(clusterCount),
    source_type: "dql_kubernetes_cluster_inventory",
    source_status: "partial",
    observed_at: observedAt,
    collection_message: "Kubernetes clusters detected; operator runtime version source not yet implemented"
  }];
}

function extractLegacyAiSummary(aiResult) {
  const raw = aiResult?.answer || aiResult?.response || aiResult?.text || aiResult?.output || "";
  const text = String(raw || "").trim();
  if (!text) {
    return { breaking_changes_summary: "", highlights_summary: "" };
  }

  const compact = text.length > 1200 ? (text.slice(0, 1197) + "...") : text;
  const breakingMatch = compact.match(/BREAKING:\s*([\s\S]*?)(?:HIGHLIGHTS:|$)/i);
  const highlightsMatch = compact.match(/HIGHLIGHTS:\s*([\s\S]*)$/i);

  function normalizeSection(value) {
    return String(value || "")
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line && line !== "-")
      .join("\n");
  }

  const breaking = normalizeSection(breakingMatch?.[1]);
  const highlights = normalizeSection(highlightsMatch?.[1]);

  return {
    breaking_changes_summary: breaking || compact,
    highlights_summary: highlights || compact
  };
}

function parsePerVersionAiMap(aiResult) {
  const out = new Map();
  const candidates = [];
  if (typeof aiResult?.per_version_json === "string") candidates.push(aiResult.per_version_json);
  if (typeof aiResult?.answer === "string") candidates.push(aiResult.answer);
  if (typeof aiResult?.response === "string") candidates.push(aiResult.response);

  for (const text of candidates) {
    const trimmed = String(text || "").trim();
    if (!trimmed) continue;

    let parsed = null;
    try {
      parsed = JSON.parse(trimmed);
    } catch (e) {
      const firstBracket = trimmed.indexOf("[");
      const lastBracket = trimmed.lastIndexOf("]");
      if (firstBracket >= 0 && lastBracket > firstBracket) {
        const snippet = trimmed.slice(firstBracket, lastBracket + 1);
        try {
          parsed = JSON.parse(snippet);
        } catch (ignored) {
          parsed = null;
        }
      }
    }

    if (!Array.isArray(parsed)) continue;

    for (const row of parsed) {
      const component = String(row?.component || "").trim();
      const releasedVersion = String(row?.released_version || row?.version || "").trim();
      if (!component || !releasedVersion) continue;
      const key = component + "|" + releasedVersion;
      out.set(key, {
        breaking_changes_summary: String(row?.breaking_changes_summary || row?.breaking || "").trim(),
        highlights_summary: String(row?.highlights_summary || row?.highlights || "").trim()
      });
    }

    if (out.size > 0) break;
  }

  return out;
}

function buildRunningVersionMap(runtimeRows) {
  const byComponent = {};
  for (const row of runtimeRows) {
    const component = String(row.component || "").trim();
    if (!component) continue;
    if (String(row.source_status || "") !== "current") continue;
    const version = String(row.observed_version || "").trim();
    if (!version) continue;

    const mode = COMPONENT_MODE[component] || "semver";
    const current = byComponent[component];
    if (!current || compareVersions(version, current, mode) > 0) {
      byComponent[component] = version;
    }
  }
  return byComponent;
}

function ensureKeySet(rows) {
  const set = new Set();
  for (const row of rows) {
    const key = String(row.component || "") + "|" + String(row.released_version || "") + "|" + String(row.is_next_planned || "false");
    set.add(key);
  }
  return set;
}

export default async function () {
  const releaseData = await result("collect_release_indexes");
  const saasData = await result("collect_saas_current_version");
  const oneagentData = await result("collect_oneagent_runtime_distribution");
  const activegateData = await result("collect_activegate_runtime_distribution");
  const operatorData = await result("collect_operator_runtime_distribution");
  const edgeconnectData = await result("collect_edgeconnect_runtime_distribution");
  const observedAt = new Date().toISOString();

  let aiData = {};
  try {
    aiData = await result("ai_summarize_release_notes");
  } catch (e) {
    aiData = {};
  }

  const legacyAiSummary = extractLegacyAiSummary(aiData);
  const perVersionAiMap = parsePerVersionAiMap(aiData);

  const oneagentRows = normalizeOneAgent(oneagentData?.records || oneagentData?.result?.records || [], observedAt);
  const saasRows = rowsFromTaskPayload(saasData, "saas", observedAt);
  const activegateRows = normalizeDistributionRows({
    component: "activegate",
    records: activegateData?.records || activegateData?.result?.records || [],
    versionField: "activegate_version",
    countField: "running_count",
    observedAt,
    sourceType: "logs_activegate_started_parse"
  });
  const operatorRows = normalizeOperatorRows(operatorData?.records || operatorData?.result?.records || [], observedAt);
  const edgeconnectRows = rowsFromTaskPayload(edgeconnectData, "edgeconnect", observedAt);

  const runtime_rows = [
    ...saasRows,
    ...oneagentRows,
    ...activegateRows,
    ...operatorRows,
    ...edgeconnectRows
  ];

  const runningVersionByComponent = buildRunningVersionMap(runtime_rows);
  const baseReleaseRows = Array.isArray(releaseData?.release_rows) ? releaseData.release_rows : [];
  const releaseCatalog = releaseData?.release_catalog && typeof releaseData.release_catalog === "object" ? releaseData.release_catalog : {};

  const release_rows = baseReleaseRows.map((r) => {
    const aiKey = String(r.component || "") + "|" + String(r.released_version || "");
    const ai = perVersionAiMap.get(aiKey);
    return {
      ...r,
      breaking_changes_summary: ai?.breaking_changes_summary || (r.is_latest === "true" ? legacyAiSummary.breaking_changes_summary : ""),
      highlights_summary: ai?.highlights_summary || (r.is_latest === "true" ? legacyAiSummary.highlights_summary : ""),
      is_newer_than_running: "false",
      newer_than_running_rank: "",
      running_version: runningVersionByComponent[r.component] || ""
    };
  });

  const existing = ensureKeySet(release_rows);

  for (const component of Object.keys(releaseCatalog)) {
    const mode = COMPONENT_MODE[component] || "semver";
    const runningVersion = runningVersionByComponent[component] || "";
    const catalogRows = Array.isArray(releaseCatalog[component]) ? releaseCatalog[component] : [];

    if (!runningVersion) continue;

    const newer = catalogRows
      .filter((row) => compareVersions(row.version, runningVersion, mode) > 0)
      .sort((a, b) => compareVersions(b.version, a.version, mode));

    let rank = 1;
    for (const row of newer) {
      const key = component + "|" + String(row.version || "") + "|false";
      const aiKey = component + "|" + String(row.version || "");
      const ai = perVersionAiMap.get(aiKey);

      if (!existing.has(key)) {
        release_rows.push({
          component,
          released_version: String(row.version || ""),
          release_status: "current",
          rollout_start_date: "",
          is_latest: "false",
          is_next_planned: "false",
          release_url: String(row.release_url || ""),
          index_url: String(row.release_url || ""),
          fetched_at: releaseData?.fetched_at || observedAt,
          breaking_changes_summary: ai?.breaking_changes_summary || "",
          highlights_summary: ai?.highlights_summary || "",
          is_newer_than_running: "true",
          newer_than_running_rank: String(rank),
          running_version: runningVersion
        });
        existing.add(key);
      }
      rank += 1;
    }
  }

  return {
    release_rows,
    runtime_rows,
    observed_at: observedAt,
    running_versions: runningVersionByComponent,
    release_catalog_count: Object.values(releaseCatalog).reduce((n, rows) => n + (Array.isArray(rows) ? rows.length : 0), 0)
  };
}

import { execution, result } from "@dynatrace-sdk/automation-utils";

function csvCell(v) {
  const s = String(v ?? "");
  const lf = String.fromCharCode(10);
  const cr = String.fromCharCode(13);
  const normalized = s.split(",").join(" ").split(lf).join(" ").split(cr).join(" ").trim();
  return normalized === "" ? "-" : normalized;
}

function toCsv(rows, headers) {
  const lines = [headers.join(",")];
  for (const row of rows) lines.push(headers.map((h) => csvCell(row[h])).join(","));
  return lines.join("\n") + "\n";
}

async function workflowConfig() {
  const ex = await execution();
  const workflowInput = ex?.input || {};
  const workflowParams = ex?.params || {};

  const releaseLookupPath = String(workflowInput.releaseLookupPath ?? workflowParams.releaseLookupPath ?? "").trim() || "/lookups/dt_component_release_status";
  const runtimeLookupPath = String(workflowInput.runtimeLookupPath ?? workflowParams.runtimeLookupPath ?? "").trim() || "/lookups/dt_component_runtime_versions";
  const locale = String(workflowInput.lookupLocale ?? workflowParams.lookupLocale ?? "").trim() || "en_US";
  const timezone = String(workflowInput.lookupTimezone ?? workflowParams.lookupTimezone ?? "").trim() || "UTC";

  return { releaseLookupPath, runtimeLookupPath, locale, timezone };
}

async function uploadLookup({ filePath, lookupField, parsePattern, headers, rows }) {
  const csv = toCsv(rows, headers);
  const cfg = await workflowConfig();
  const request = {
    filePath,
    lookupField,
    overwrite: true,
    displayName: filePath.split("/").pop(),
    description: "Generated by Version Intelligence Sync",
    skippedRecords: 1,
    autoFlatten: true,
    timezone: cfg.timezone,
    locale: cfg.locale,
    parsePattern
  };

  const blob = new Blob([csv], { type: "text/csv" });
  const file = new File([blob], lookupField + ".csv", { type: "text/csv" });
  const formData = new FormData();
  formData.append("request", JSON.stringify(request));
  formData.append("content", file);

  const response = await fetch("/platform/storage/resource-store/v1/files/tabular/lookup:upload", {
    method: "POST",
    body: formData
  });

  if (!response.ok) {
    const body = await response.text();
    throw new Error("Lookup upload failed for " + filePath + ": " + response.status + " " + body);
  }
  const responseBody = await response.text();
  return { filePath, statusCode: response.status, rowCount: rows.length, response: responseBody };
}

